func administrationUserName(user auth.ManagedUser) string {
	if user.DisplayName != "" {
		return user.DisplayName
	}
	return user.Username
}
func roleHasSurface(role auth.Role, surface auth.Surface) bool {
	for _, grant := range role.Grants {
		if grant.Surface == surface {
			return true
		}
	}
	return false
}
func userHasWebAccess(view AdministrationPageView, user auth.ManagedUser) bool {
	for _, role := range view.Roles {
		if adminContains(user.Roles, role.Name) && roleHasSurface(role, auth.SurfaceWeb) {
			return true
		}
	}
	return false
}
func adminContains(values []string, value string) bool {
	for _, item := range values {
		if item == value {
			return true
		}
	}
	return false
}
func adminTime(value time.Time, display TimeDisplay) string { return FormatDateTime(value, display) }
func tokenLastUsed(value time.Time, display TimeDisplay) string {
	if value.IsZero() {
		return "Never used"
	}
	return adminTime(value, display)
}
func userTokenCount(view AdministrationPageView, userID int64) int {
	count := 0
	for _, token := range view.Tokens {
		if token.UserID == userID {
			count++
		}
	}
	return count
}

func tokenLifetimeLabel(value time.Duration) string {
	if value <= 0 {
		return "server default"
	}
	if value%(24*time.Hour) == 0 {
		days := int(value / (24 * time.Hour))
		if days == 1 {
			return "1 day"
		}
		return fmt.Sprintf("%d days", days)
	}
	return value.String()
}
func adminPlural(count int, singular, plural string) string {
	if count == 1 {
		return singular
	}
	return plural
}
func adminUserDialogID(id int64) string      { return fmt.Sprintf("edit-user-%d-dialog", id) }
func adminUserProfileFormID(id int64) string { return fmt.Sprintf("edit-user-%d-profile", id) }
func adminUserGroupsFormID(id int64) string  { return fmt.Sprintf("edit-user-%d-groups", id) }
func adminUserTokenCountID(id int64) string  { return fmt.Sprintf("edit-user-%d-token-count", id) }
func adminGroupDialogID(id int64) string     { return fmt.Sprintf("edit-group-%d-dialog", id) }
func adminRoles(roles []string) string {
	if len(roles) == 0 {
		return "No groups"
	}
	return strings.Join(roles, ", ")
}
func permissionRoleCount(roles []auth.Role, permission string) int {
	return len(permissionRoles(roles, permission))
}
func permissionRoles(roles []auth.Role, permission string) []string {
	result := make([]string, 0)
	for _, role := range roles {
		if adminContains(role.Permissions, auth.PermissionAll) || adminContains(role.Permissions, permission) {
			result = append(result, role.Name)
		}
	}
	return result
}
func permissionRolesForSurface(roles []auth.Role, permission string, surface auth.Surface) []string {
	result := make([]string, 0)
	for _, role := range roles {
		for _, grant := range role.Grants {
			if grant.Surface == surface && (grant.Permission == permission || grant.Permission == auth.PermissionAll) {
				result = append(result, role.Name)
				break
			}
		}
	}
	return result
}
func permissionResourceLabel(permission string) string {
	if strings.HasPrefix(permission, "zones.") && permission != auth.PermissionZonesCreate {
		return "All or selected zones"
	}
	return "Global"
}
func roleHasGrant(role *auth.Role, surface auth.Surface, permission string) bool {
	if role == nil {
		return false
	}
	for _, grant := range role.Grants {
		if grant.Surface == surface && (grant.Permission == permission || grant.Permission == auth.PermissionAll) {
			return true
		}
	}
	return false
}
func roleUsesAllZones(role *auth.Role, surface auth.Surface) bool {
	if role == nil {
		return false
	}
	for _, grant := range role.Grants {
		if grant.Surface == surface && grant.ResourceType == auth.ResourceZone && grant.ResourceID == auth.ResourceAll {
			return true
		}
	}
	return false
}
func roleUsesSelectedZones(role *auth.Role, surface auth.Surface) bool {
	if role == nil || roleUsesAllZones(role, surface) {
		return false
	}
	for _, grant := range role.Grants {
		if grant.Surface == surface && grant.ResourceType == auth.ResourceZone && grant.ResourceID != "" {
			return true
		}
	}
	return false
}
func roleHasZone(role *auth.Role, surface auth.Surface, zoneID string) bool {
	if role == nil {
		return false
	}
	for _, grant := range role.Grants {
		if grant.Surface == surface && grant.ResourceType == auth.ResourceZone && grant.ResourceID == zoneID {
			return true
		}
	}
	return false
}
func roleHasAPIAccess(role auth.Role) bool {
	for _, grant := range role.Grants {
		if grant.Surface == auth.SurfaceAPI {
			return true
		}
	}
	return false
}
func tokenRoleAssigned(view AdministrationPageView, userID int64, roleName string) bool {
	for _, user := range view.Users {
		if user.ID == userID {
			return adminContains(user.Roles, roleName)
		}
	}
	return false
}
func tokenRoleUserIDs(view AdministrationPageView, roleName string) string {
	result := make([]string, 0)
	for _, user := range view.Users {
		if !user.Disabled && adminContains(user.Roles, roleName) {
			result = append(result, fmt.Sprint(user.ID))
		}
	}
	return strings.Join(result, ",")
}
func tokenRoles(view AdministrationPageView) []auth.Role {
	result := make([]auth.Role, 0)
	for _, role := range view.Roles {
		if roleHasAPIAccess(role) {
			result = append(result, role)
		}
	}
	return result
}
func apiGrantSummary(role auth.Role) string {
	count := 0
	allZones := false
	selectedZones := map[string]struct{}{}
	for _, grant := range role.Grants {
		if grant.Surface != auth.SurfaceAPI {
			continue
		}
		count++
		if grant.ResourceType == auth.ResourceZone {
			if grant.ResourceID == auth.ResourceAll {
				allZones = true
			} else {
				selectedZones[grant.ResourceID] = struct{}{}
			}
		}
	}
	scope := "global permissions"
	if allZones {
		scope = "all zones"
	} else if len(selectedZones) > 0 {
		scope = fmt.Sprintf("%d selected zones", len(selectedZones))
	}
	return fmt.Sprintf("%d API grants · %s", count, scope)
}

